/**
 * Readable IDs (URL slugs) that the app makes up itself. Record IDs are UUIDs generated by
 * PostgreSQL (uuid_generate_v4()) and never need this.
 */

type Db = { query: (text: string, params?: any[]) => Promise<any> };

/** Tables whose `slug` column is UNIQUE. The name goes into SQL, so it must come from this list. */
export type SlugTable = 'stories' | 'translation_groups' | 'posts';

/**
 * The first slug not used yet in `table`: `base` itself, else `base-2`, `base-3`, ...
 * `base` must already be slugified (only a-z, 0-9 and "-").
 */
export async function nextFreeSlug(db: Db, table: SlugTable, base: string): Promise<string> {
  const clean = base.slice(0, 480).replace(/-+$/, '') || 'muc';
  const res = await db.query(`SELECT slug FROM ${table} WHERE slug = $1 OR slug LIKE $2`, [clean, `${clean}-%`]);
  const taken = new Set<string>(res.rows.map((r: any) => r.slug));
  if (!taken.has(clean)) return clean;
  for (let n = 2; ; n++) {
    const candidate = `${clean}-${n}`;
    if (!taken.has(candidate)) return candidate;
  }
}

/**
 * Runs `insert(slug)` with a free slug. If another request took the same slug between the check
 * and the insert (unique violation), it picks the next free slug and tries again.
 * Pass inTransaction=true when `db` is a client inside BEGIN: each attempt then runs under a
 * savepoint, so a failed attempt doesn't abort the caller's transaction.
 */
export async function insertWithUniqueSlug<T>(
  db: Db,
  table: SlugTable,
  base: string,
  insert: (slug: string) => Promise<T>,
  inTransaction = false
): Promise<T> {
  for (let attempt = 0; attempt < 5; attempt++) {
    const slug = await nextFreeSlug(db, table, base);
    if (inTransaction) await db.query('SAVEPOINT unique_slug');
    try {
      const result = await insert(slug);
      if (inTransaction) await db.query('RELEASE SAVEPOINT unique_slug');
      return result;
    } catch (err: any) {
      if (inTransaction) await db.query('ROLLBACK TO SAVEPOINT unique_slug');
      if (err?.code === '23505' && String(err.constraint || '').includes('slug')) continue;
      throw err;
    }
  }
  throw new Error(`Không tìm được slug trống cho "${base}"`);
}
